        {setup.names.slice(0, setup.count).map((name, index) => (
          <div className="tournament-field" key={index}>
            <label htmlFor={`tournament-player-${index}`}>Player {index + 1}</label>
            <input id={`tournament-player-${index}`} className="control" value={name}
              autoComplete="off" aria-invalid={Boolean(errors[index])}
              aria-describedby={errors[index] ? `player-error-${index}` : undefined}
              onChange={(event) => change({ ...setup,
                names: setup.names.map((value, other) => other === index ? event.currentTarget.value : value),
              })} />
            {errors[index] && <p id={`player-error-${index}`}>{errors[index]}</p>}
          </div>
        ))}
      </div>
      <button className="control" type="submit">Start tournament</button>
    </form>
